export function createAnnouncementsUI({e,link}){
 const hidden=(k,v)=>'<input type="hidden" name="'+k+'" value="'+e(v)+'">';
 function page(room,staff,p){const id=room.class.id,archived=staff&&p.get('postStatus')==='archived',query=(p.get('postSearch')||'').trim().toLocaleLowerCase(),rows=room.posts.filter(r=>!!r.archived===archived&&(!query||(r.title+' '+r.body).toLocaleLowerCase().includes(query))),limit=6,n=Number(p.get('postOffset')||0),offset=rows.length?Math.min(Number.isSafeInteger(n)&&n>=0?Math.floor(n/limit)*limit:0,Math.floor((rows.length-1)/limit)*limit):0,base={class:id,tab:'stream',...(archived?{postStatus:'archived'}:{}),...(query?{postSearch:p.get('postSearch')}:{})};return '<div class="learning-section-title"><h2>Class stream</h2><span>'+rows.length+' '+(rows.length===1?'announcement':'announcements')+'</span></div>'+(staff?'<details class="vle-panel"><summary>Share an announcement</summary><form data-vle="post">'+hidden('classId',id)+'<label class="vle-field">Title<input name="title" maxlength="160" required></label><label class="vle-field">Announcement<textarea name="body" maxlength="10000" required></textarea></label><button class="btn primary">Post announcement</button></form></details>':'')+'<form data-announcement-filters class="community-filters">'+hidden('class',id)+hidden('tab','stream')+(staff?'<label>Show<select name="postStatus" aria-label="Announcement visibility"><option value="available">Available</option><option value="archived" '+(archived?'selected':'')+'>Archived</option></select></label>':'')+'<label>Find<input name="postSearch" aria-label="Find announcements" maxlength="120" value="'+e(p.get('postSearch')||'')+'" placeholder="Title or message"></label><button class="btn">Find announcements</button>'+link('Clear filters',{class:id,tab:'stream'})+'</form>'+rows.slice(offset,offset+limit).map(r=>'<article class="vle-panel"><small>'+(r.pinned?'Pinned · ':'')+e(r.author)+' · '+e(new Date(r.updatedAt||r.createdAt).toLocaleDateString('en-GB'))+(r.archived?' · Archived':'')+'</small><h3>'+e(r.title)+'</h3><p class="vle-prose">'+e(r.body)+'</p>'+(staff?(!r.archived?'<details><summary>Edit announcement</summary><form data-vle="post-update">'+hidden('id',r.id)+hidden('expectedRevision',r.revision||1)+'<label class="vle-field">Title<input name="title" maxlength="160" required value="'+e(r.title)+'"></label><label class="vle-field">Announcement<textarea name="body" maxlength="10000" required>'+e(r.body)+'</textarea></label><label><input type="checkbox" name="pinned" '+(r.pinned?'checked':'')+'> Pin to top</label><div class="vle-actions"><button class="btn primary">Save announcement</button></div></form></details>':'')+'<form data-vle="post-archive">'+hidden('id',r.id)+hidden('expectedRevision',r.revision||1)+hidden('archived',!r.archived)+'<button class="btn">'+(r.archived?'Restore announcement':'Archive announcement')+'</button></form>':'')+'</article>').join('')+(!rows.length?'<p class="learning-empty">'+(query?'No announcements match your search.':archived?'No archived announcements.':'No announcements yet. Open Classwork for assignments and Materials for class guides.')+'</p>':'')+'<div class="vle-actions">'+(offset?link('← Previous',{...base,postOffset:offset-limit}):'')+(offset+limit<rows.length?link('Next →',{...base,postOffset:offset+limit}):'')+'</div>';}
 function bind(root){root.querySelector('[data-announcement-filters]')?.addEventListener('submit',ev=>{ev.preventDefault();location.hash='/classroom?'+new URLSearchParams([...new FormData(ev.currentTarget)].filter(([,v])=>v));});}return{page,bind};
}
